diff --git a/src/scheduler.js b/src/scheduler.js
index 05ca288..2974d27 100644
--- a/src/scheduler.js
+++ b/src/scheduler.js
@@ -1,2 +1,149 @@
-export function createScheduler() { throw new Error('Not implemented'); }
-export function restoreScheduler() { throw new Error('Not implemented'); }
+const TERMINAL = new Set(['done', 'dead', 'cancelled', 'blocked']);
+const UNSUCCESSFUL = new Set(['dead', 'cancelled', 'blocked']);
+const clone = value => value === undefined ? undefined : structuredClone(value);
+const error = code => Object.assign(new Error(code), { code });
+const validName = value => typeof value === 'string' && value.length > 0;
+const validPositive = value => Number.isSafeInteger(value) && value > 0;
+const validTime = value => Number.isSafeInteger(value) && value >= 0;
+
+export function createScheduler(options = {}) {
+  if (options === null || typeof options !== 'object' || Array.isArray(options)) throw error('INVALID_INPUT');
+  const { now = 0, retryBase = 2, maxAttempts = 3 } = options;
+  if (!validTime(now) || !validPositive(retryBase) || !validPositive(maxAttempts)) throw error('INVALID_INPUT');
+  return build({ schemaVersion: 1, now, retryBase, maxAttempts, nextSequence: 0, nextToken: 1, jobs: [] });
+}
+
+export function restoreScheduler(snapshot) {
+  // Snapshots produced here are self-contained; clone to keep both histories independent.
+  return build(clone(snapshot));
+}
+
+function build(state) {
+  const jobs = new Map(state.jobs.map(job => [job.id, clone(job)]));
+
+  function view(job) { return clone(job); }
+  function required(id) {
+    const job = jobs.get(id);
+    if (!job) throw error('UNKNOWN_JOB');
+    return job;
+  }
+  function blockedBy(job) {
+    return job.dependsOn.find(id => UNSUCCESSFUL.has(jobs.get(id).status));
+  }
+  function refreshDependents(id) {
+    for (const job of jobs.values()) {
+      if (!job.dependsOn.includes(id) || TERMINAL.has(job.status)) continue;
+      const blocker = blockedBy(job);
+      if (blocker !== undefined) {
+        clearLease(job);
+        job.status = 'blocked';
+        job.blockedBy = blocker;
+        refreshDependents(job.id);
+      } else if (job.dependsOn.every(dep => jobs.get(dep).status === 'done') && job.status === 'waiting') {
+        job.status = 'ready';
+      }
+    }
+  }
+  function clearLease(job) {
+    delete job.worker;
+    delete job.token;
+    delete job.leaseUntil;
+  }
+  function lease(id, worker, token) {
+    const job = required(id);
+    if (job.status !== 'leased' || job.worker !== worker || job.token !== token) throw error('LEASE_LOST');
+    return job;
+  }
+  function finishFailure(job, reason) {
+    job.lastError = reason;
+    clearLease(job);
+    if (job.attempt < state.maxAttempts) {
+      job.status = 'ready';
+      job.availableAt = state.now + state.retryBase * (2 ** (job.attempt - 1));
+    } else {
+      job.status = 'dead';
+      refreshDependents(job.id);
+    }
+  }
+
+  return {
+    submit(input = {}) {
+      if (input === null || typeof input !== 'object' || Array.isArray(input)) throw error('INVALID_INPUT');
+      const { id, dependsOn = [], priority = 0 } = input;
+      if (!validName(id) || !Number.isSafeInteger(priority)) throw error('INVALID_INPUT');
+      if (jobs.has(id)) throw error('JOB_EXISTS');
+      if (!Array.isArray(dependsOn) || dependsOn.some(dep => !validName(dep)) || new Set(dependsOn).size !== dependsOn.length || dependsOn.includes(id)) throw error('INVALID_DEPENDENCIES');
+      if (dependsOn.some(dep => !jobs.has(dep))) throw error('UNKNOWN_DEPENDENCY');
+      const job = { id, dependsOn: clone(dependsOn), priority, sequence: state.nextSequence++, status: 'ready', attempt: 0, availableAt: state.now };
+      const blocker = blockedBy(job);
+      if (blocker !== undefined) {
+        job.status = 'blocked';
+        job.blockedBy = blocker;
+      } else if (!dependsOn.every(dep => jobs.get(dep).status === 'done')) job.status = 'waiting';
+      jobs.set(id, job);
+      return view(job);
+    },
+    get(id) { return view(required(id)); },
+    claim(input = {}) {
+      if (input === null || typeof input !== 'object' || Array.isArray(input)) throw error('INVALID_INPUT');
+      const { worker, leaseFor } = input;
+      if (!validName(worker) || !validPositive(leaseFor)) throw error('INVALID_INPUT');
+      const job = [...jobs.values()].filter(item => item.status === 'ready' && item.availableAt <= state.now)
+        .sort((a, b) => b.priority - a.priority || a.sequence - b.sequence || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
+      if (!job) return null;
+      job.status = 'leased';
+      job.attempt += 1;
+      job.worker = worker;
+      job.token = state.nextToken++;
+      job.leaseUntil = state.now + leaseFor;
+      return view(job);
+    },
+    renew(input = {}) {
+      if (input === null || typeof input !== 'object' || Array.isArray(input)) throw error('INVALID_INPUT');
+      const { id, worker, token, leaseFor } = input;
+      if (!validPositive(leaseFor)) throw error('INVALID_INPUT');
+      const job = lease(id, worker, token);
+      job.leaseUntil = Math.max(job.leaseUntil, state.now + leaseFor);
+      return view(job);
+    },
+    complete(input = {}) {
+      if (input === null || typeof input !== 'object' || Array.isArray(input)) throw error('INVALID_INPUT');
+      const { id, worker, token, result } = input;
+      const job = lease(id, worker, token);
+      if (result !== undefined) job.result = clone(result);
+      delete job.lastError;
+      clearLease(job);
+      job.status = 'done';
+      refreshDependents(job.id);
+      return view(job);
+    },
+    fail(input = {}) {
+      if (input === null || typeof input !== 'object' || Array.isArray(input)) throw error('INVALID_INPUT');
+      const { id, worker, token, error: reason } = input;
+      if (!validName(reason)) throw error('INVALID_INPUT');
+      const job = lease(id, worker, token);
+      finishFailure(job, reason);
+      return view(job);
+    },
+    cancel(id) {
+      const job = required(id);
+      if (TERMINAL.has(job.status)) throw error('JOB_TERMINAL');
+      clearLease(job);
+      job.status = 'cancelled';
+      refreshDependents(job.id);
+      return view(job);
+    },
+    advance(time) {
+      if (!validTime(time) || time < state.now) throw error('INVALID_TIME');
+      state.now = time;
+      const expired = [...jobs.values()].filter(job => job.status === 'leased' && job.leaseUntil <= time)
+        .sort((a, b) => a.leaseUntil - b.leaseUntil || a.sequence - b.sequence);
+      for (const job of expired) finishFailure(job, 'LEASE_EXPIRED');
+      return { now: state.now, expired: expired.map(job => job.id) };
+    },
+    snapshot() {
+      return { schemaVersion: 1, now: state.now, retryBase: state.retryBase, maxAttempts: state.maxAttempts,
+        nextSequence: state.nextSequence, nextToken: state.nextToken, jobs: [...jobs.values()].map(view) };
+    }
+  };
+}
diff --git a/tests/scheduler.acceptance.test.js b/tests/scheduler.acceptance.test.js
new file mode 100644
index 0000000..8dfd125
--- /dev/null
+++ b/tests/scheduler.acceptance.test.js
@@ -0,0 +1,245 @@
+import { describe, expect, it } from 'vitest';
+import { createScheduler, restoreScheduler } from '../src/scheduler.js';
+
+const codeOf = (run, code) => {
+  try { run(); } catch (error) { expect(error.code).toBe(code); return; }
+  throw new Error(`Expected ${code}`);
+};
+
+describe('PulseGraph scheduler acceptance', () => {
+  it('[R-1] exports both constructors and all public operations', () => {
+    expect(typeof createScheduler).toBe('function');
+    expect(typeof restoreScheduler).toBe('function');
+    const scheduler = createScheduler();
+    for (const method of ['submit', 'get', 'claim', 'renew', 'complete', 'fail', 'cancel', 'advance', 'snapshot']) {
+      expect(typeof scheduler[method]).toBe('function');
+    }
+  });
+
+  it('[R-2] validates names, priority, scheduler options, and preserves ID uniqueness', () => {
+    for (const options of [{ now: -1 }, { now: 1.5 }, { retryBase: 0 }, { maxAttempts: Number.MAX_SAFE_INTEGER + 1 }]) {
+      codeOf(() => createScheduler(options), 'INVALID_INPUT');
+    }
+    const scheduler = createScheduler({ now: 4 });
+    for (const id of ['', 3, null]) codeOf(() => scheduler.submit({ id }), 'INVALID_INPUT');
+    for (const priority of [1.2, Number.MAX_SAFE_INTEGER + 1]) codeOf(() => scheduler.submit({ id: `p${priority}`, priority }), 'INVALID_INPUT');
+    scheduler.submit({ id: 'forever' });
+    scheduler.cancel('forever');
+    codeOf(() => scheduler.submit({ id: 'forever' }), 'JOB_EXISTS');
+    codeOf(() => scheduler.claim({ worker: '', leaseFor: 1 }), 'INVALID_INPUT');
+    for (const leaseFor of [0, 1.5]) codeOf(() => scheduler.claim({ worker: 'worker', leaseFor }), 'INVALID_INPUT');
+  });
+
+  it('[R-3] rejects invalid, duplicate, self, and unknown dependencies atomically', () => {
+    const scheduler = createScheduler();
+    scheduler.submit({ id: 'known' });
+    for (const { id, dependsOn } of [
+      { id: 'duplicate', dependsOn: ['known', 'known'] },
+      { id: 'self', dependsOn: ['self'] },
+      { id: 'empty-dependency', dependsOn: [''] },
+      { id: 'non-array', dependsOn: 'known' }
+    ]) {
+      codeOf(() => scheduler.submit({ id, dependsOn }), 'INVALID_DEPENDENCIES');
+      codeOf(() => scheduler.get(id), 'UNKNOWN_JOB');
+    }
+    codeOf(() => scheduler.submit({ id: 'missing', dependsOn: ['absent'] }), 'UNKNOWN_DEPENDENCY');
+    codeOf(() => scheduler.submit({ id: 'known' }), 'JOB_EXISTS');
+  });
+
+  it('[R-4] submits atomically with initial fields and dependency-derived status', () => {
+    const scheduler = createScheduler({ now: 7, maxAttempts: 1 });
+    scheduler.submit({ id: 'done-dep' });
+    let lease = scheduler.claim({ worker: 'w', leaseFor: 1 });
+    scheduler.complete({ id: 'done-dep', worker: 'w', token: lease.token, result: null });
+    scheduler.submit({ id: 'dead-dep' });
+    lease = scheduler.claim({ worker: 'w', leaseFor: 1 });
+    scheduler.fail({ id: 'dead-dep', worker: 'w', token: lease.token, error: 'nope' });
+    const root = scheduler.submit({ id: 'ready' });
+    const waiting = scheduler.submit({ id: 'waiting', dependsOn: ['ready'] });
+    const readyFromDone = scheduler.submit({ id: 'from-done', dependsOn: ['done-dep'] });
+    const blocked = scheduler.submit({ id: 'from-dead', dependsOn: ['dead-dep'] });
+    expect(root).toMatchObject({ status: 'ready', attempt: 0, availableAt: 7 });
+    expect(root).not.toHaveProperty('result');
+    expect(root).not.toHaveProperty('lastError');
+    expect(waiting.status).toBe('waiting');
+    expect(readyFromDone.status).toBe('ready');
+    expect(blocked).toMatchObject({ status: 'blocked', blockedBy: 'dead-dep' });
+  });
+
+  it('[R-5] releases completed dependencies and propagates the first blocker transitively', () => {
+    const scheduler = createScheduler({ maxAttempts: 1 });
+    scheduler.submit({ id: 'a' });
+    scheduler.submit({ id: 'b', dependsOn: ['a'] });
+    scheduler.submit({ id: 'c', dependsOn: ['b'] });
+    const claimed = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    scheduler.complete({ id: 'a', worker: 'w', token: claimed.token, result: true });
+    expect(scheduler.get('b').status).toBe('ready');
+    const b = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    scheduler.fail({ id: 'b', worker: 'w', token: b.token, error: 'failed' });
+    expect(scheduler.get('c')).toMatchObject({ status: 'blocked', blockedBy: 'b' });
+
+    const other = createScheduler({ maxAttempts: 1 });
+    for (const id of ['x', 'y', 'z']) other.submit({ id });
+    const x = other.claim({ worker: 'w', leaseFor: 1 });
+    other.fail({ id: x.id, worker: 'w', token: x.token, error: 'failed' });
+    const dependent = other.submit({ id: 'multi', dependsOn: ['y', 'z', 'x'] });
+    expect(dependent.blockedBy).toBe('x');
+  });
+
+  it('[R-6] returns detached views with optional fields only in applicable states', () => {
+    const scheduler = createScheduler();
+    const dependencies = [];
+    const submitted = scheduler.submit({ id: 'job', dependsOn: dependencies });
+    expect(submitted).toMatchObject({ id: 'job', dependsOn: [], priority: 0, sequence: 0, status: 'ready', attempt: 0, availableAt: 0 });
+    submitted.dependsOn.push('mutated');
+    expect(scheduler.get('job').dependsOn).toEqual([]);
+    expect(scheduler.get('job')).not.toHaveProperty('blockedBy');
+    expect(scheduler.get('job')).not.toHaveProperty('worker');
+    const leased = scheduler.claim({ worker: 'w', leaseFor: 5 });
+    expect(leased).toMatchObject({ status: 'leased', worker: 'w', token: 1, leaseUntil: 5 });
+    expect(scheduler.get('job')).not.toHaveProperty('blockedBy');
+    expect(scheduler.get('job')).not.toHaveProperty('result');
+  });
+
+  it('[R-7] claims available jobs by priority then submission order and increments tokens', () => {
+    const scheduler = createScheduler();
+    scheduler.submit({ id: 'first', priority: 1 });
+    scheduler.submit({ id: 'high', priority: 2 });
+    scheduler.submit({ id: 'same-priority-next', priority: 1 });
+    expect(scheduler.claim({ worker: 'w', leaseFor: 3 })).toMatchObject({ id: 'high', attempt: 1, token: 1, leaseUntil: 3 });
+    expect(scheduler.claim({ worker: 'w', leaseFor: 3 }).id).toBe('first');
+    expect(scheduler.claim({ worker: 'w', leaseFor: 3 }).id).toBe('same-priority-next');
+    expect(scheduler.claim({ worker: 'w', leaseFor: 3 })).toBeNull();
+  });
+
+  it('[R-8] validates leases, renews them, and completes with detached results', () => {
+    const scheduler = createScheduler();
+    scheduler.submit({ id: 'job' });
+    const claimed = scheduler.claim({ worker: 'w', leaseFor: 3 });
+    expect(scheduler.renew({ id: 'job', worker: 'w', token: claimed.token, leaseFor: 1 }).leaseUntil).toBe(3);
+    expect(scheduler.renew({ id: 'job', worker: 'w', token: claimed.token, leaseFor: 5 })).toMatchObject({ token: claimed.token, leaseUntil: 5 });
+    codeOf(() => scheduler.renew({ id: 'job', worker: 'other', token: claimed.token, leaseFor: 1 }), 'LEASE_LOST');
+    const value = { rows: [1] };
+    const completed = scheduler.complete({ id: 'job', worker: 'w', token: claimed.token, result: value });
+    value.rows.push(2);
+    completed.result.rows.push(3);
+    expect(scheduler.get('job')).toMatchObject({ status: 'done', result: { rows: [1] } });
+    expect(scheduler.get('job')).not.toHaveProperty('worker');
+    codeOf(() => scheduler.complete({ id: 'job', worker: 'w', token: claimed.token }), 'LEASE_LOST');
+
+    const retried = createScheduler({ retryBase: 3, maxAttempts: 2 });
+    retried.submit({ id: 'retry' });
+    const failedAttempt = retried.claim({ worker: 'w', leaseFor: 2 });
+    retried.fail({ id: 'retry', worker: 'w', token: failedAttempt.token, error: 'transient' });
+    retried.advance(3);
+    const secondAttempt = retried.claim({ worker: 'w', leaseFor: 2 });
+    const retriedResult = retried.complete({ id: 'retry', worker: 'w', token: secondAttempt.token, result: 'ok' });
+    expect(retriedResult).not.toHaveProperty('lastError');
+  });
+
+  it('[R-9] retries with exponential delay and marks the final failed attempt dead', () => {
+    const scheduler = createScheduler({ retryBase: 2, maxAttempts: 2 });
+    scheduler.submit({ id: 'job' });
+    let claimed = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    expect(scheduler.fail({ id: 'job', worker: 'w', token: claimed.token, error: 'first' })).toMatchObject({ status: 'ready', availableAt: 2, lastError: 'first' });
+    expect(scheduler.claim({ worker: 'w', leaseFor: 1 })).toBeNull();
+    scheduler.advance(2);
+    claimed = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    expect(claimed.attempt).toBe(2);
+    expect(scheduler.fail({ id: 'job', worker: 'w', token: claimed.token, error: 'last' })).toMatchObject({ status: 'dead', lastError: 'last' });
+    codeOf(() => scheduler.fail({ id: 'job', worker: 'w', token: claimed.token, error: '' }), 'INVALID_INPUT');
+  });
+
+  it('[R-10] cancels leased work, blocks descendants, and rejects terminal or unknown IDs', () => {
+    const scheduler = createScheduler();
+    scheduler.submit({ id: 'parent' });
+    scheduler.submit({ id: 'child', dependsOn: ['parent'] });
+    const lease = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    expect(scheduler.cancel('parent').status).toBe('cancelled');
+    expect(scheduler.get('child')).toMatchObject({ status: 'blocked', blockedBy: 'parent' });
+    codeOf(() => scheduler.complete({ id: 'parent', worker: 'w', token: lease.token }), 'LEASE_LOST');
+    codeOf(() => scheduler.cancel('parent'), 'JOB_TERMINAL');
+    codeOf(() => scheduler.get('missing'), 'UNKNOWN_JOB');
+    codeOf(() => scheduler.cancel('missing'), 'UNKNOWN_JOB');
+  });
+
+  it('[R-11] advances monotonically and expires leases by deadline then submission order', () => {
+    const scheduler = createScheduler({ maxAttempts: 1 });
+    for (const id of ['first', 'second', 'later']) scheduler.submit({ id });
+    scheduler.claim({ worker: 'w', leaseFor: 3 });
+    scheduler.claim({ worker: 'w', leaseFor: 2 });
+    scheduler.claim({ worker: 'w', leaseFor: 3 });
+    const before = scheduler.snapshot();
+    for (const time of [-1, 1.1, Number.MAX_SAFE_INTEGER + 1]) codeOf(() => scheduler.advance(time), 'INVALID_TIME');
+    expect(scheduler.snapshot()).toEqual(before);
+    expect(scheduler.advance(3)).toEqual({ now: 3, expired: ['second', 'first', 'later'] });
+    expect(scheduler.get('first')).toMatchObject({ status: 'dead', lastError: 'LEASE_EXPIRED' });
+  });
+
+  it('[R-12] does not expire leases during claim and advance invalidates expired tokens', () => {
+    const scheduler = createScheduler({ now: 0, maxAttempts: 2 });
+    scheduler.submit({ id: 'job' });
+    const lease = scheduler.claim({ worker: 'w', leaseFor: 1 });
+    scheduler.advance(1);
+    codeOf(() => scheduler.renew({ id: 'job', worker: 'w', token: lease.token, leaseFor: 1 }), 'LEASE_LOST');
+    expect(scheduler.get('job').status).toBe('ready');
+    scheduler.submit({ id: 'next' });
+    expect(scheduler.claim({ worker: 'w', leaseFor: 1 }).token).toBe(2);
+  });
+
+  it('[R-13] snapshots exactly the schema and complete per-job views', () => {
+    const scheduler = createScheduler();
+    scheduler.submit({ id: 'job' });
+    const lease = scheduler.claim({ worker: 'w', leaseFor: 2 });
+    const snapshot = scheduler.snapshot();
+    expect(Object.keys(snapshot)).toEqual(['schemaVersion', 'now', 'retryBase', 'maxAttempts', 'nextSequence', 'nextToken', 'jobs']);
+    expect(snapshot.jobs[0]).toEqual(lease);
+  });
+
+  it('[R-14] isolates inputs, results, views, snapshots, and restored scheduler histories', () => {
+    const scheduler = createScheduler();
+    const dependencies = [];
+    scheduler.submit({ id: 'job', dependsOn: dependencies });
+    scheduler.submit({ id: 'queued' });
+    dependencies.push('later-mutation');
+    const lease = scheduler.claim({ worker: 'w', leaseFor: 10 });
+    const snapshot = scheduler.snapshot();
+    snapshot.jobs[0].dependsOn.push('snapshot-mutation');
+    snapshot.jobs[0].worker = 'changed';
+    const restored = restoreScheduler(JSON.parse(JSON.stringify(scheduler.snapshot())));
+    const originalNext = scheduler.claim({ worker: 'w2', leaseFor: 1 });
+    const restoredNext = restored.claim({ worker: 'w2', leaseFor: 1 });
+    expect(originalNext).toMatchObject({ id: 'queued', token: 2 });
+    expect(restoredNext).toMatchObject({ id: 'queued', token: 2 });
+    expect(scheduler.get('job').token).toBe(lease.token);
+    expect(restored.get('job').token).toBe(lease.token);
+    expect(scheduler.get('job').dependsOn).toEqual([]);
+
+    const history = createScheduler({ now: 4, retryBase: 3, maxAttempts: 2 });
+    history.submit({ id: 'done' });
+    let historyLease = history.claim({ worker: 'w', leaseFor: 2 });
+    history.complete({ id: 'done', worker: 'w', token: historyLease.token, result: { ok: true } });
+    history.submit({ id: 'retry' });
+    historyLease = history.claim({ worker: 'w', leaseFor: 2 });
+    history.fail({ id: 'retry', worker: 'w', token: historyLease.token, error: 'transient' });
+    history.submit({ id: 'cancelled' });
+    history.cancel('cancelled');
+    history.submit({ id: 'blocked', dependsOn: ['cancelled'] });
+    history.submit({ id: 'available' });
+    const historyClone = restoreScheduler(JSON.parse(JSON.stringify(history.snapshot())));
+    expect(historyClone.snapshot()).toEqual(history.snapshot());
+    expect(historyClone.snapshot()).toMatchObject({ now: 4, retryBase: 3, maxAttempts: 2, nextToken: 3 });
+    expect(historyClone.claim({ worker: 'clone', leaseFor: 1 }).token).toBe(3);
+    expect(history.claim({ worker: 'original', leaseFor: 1 }).token).toBe(3);
+
+    const isolated = createScheduler();
+    isolated.submit({ id: 'result' });
+    const claim = isolated.claim({ worker: 'w', leaseFor: 1 });
+    const result = { nested: { value: 1 } };
+    isolated.complete({ id: 'result', worker: 'w', token: claim.token, result });
+    result.nested.value = 2;
+    const returned = isolated.get('result');
+    returned.result.nested.value = 3;
+    expect(isolated.get('result').result.nested.value).toBe(1);
+  });
+});
